const RACES = {"human": {"cn": "人类", "desc": "大陆数量最多、适应力最强的种族。七大地域孕育出七种截然不同的活法。", "ic": "🧑"}, "half": {"cn": "混血", "desc": "人类与其他种族的血脉交汇。长寿与短命、偏见与机遇，都写在血脉里。", "ic": "🌓"}, "elf": {"cn": "精灵", "desc": "长寿的森林之民。魔法天赋流淌在血脉里，岁月在他们脸上刻下宁静。", "ic": "🧝"}, "dwarf": {"cn": "矮人", "desc": "山腹与熔炉之子。短矮的身躯里装着铁一般的意志与手艺。", "ic": "🧔"}, "orc": {"cn": "兽人", "desc": "草原与蛮荒的战士。力量与战意是他们的第一语言。", "ic": "👹"}, "halfling": {"cn": "半身人", "desc": "田野与市井间的小个子。幸运仿佛偏爱他们，麻烦也总绕着他们走。", "ic": "🍀"}, "dragon": {"cn": "龙裔", "desc": "体内流淌着巨龙血脉的古老种族。鳞片、吐息与血脉的骄傲。", "ic": "🐉"}}; window.RACES = RACES; /* /v60inj:winx2:RACES/ */
const SUBRACES = {"nordic": {"cn": "北境人", "race": "human", "attrs": {"STR": 2, "CON": 1}, "skills": {"survive": 5}, "traits": ["寒冷抗性"], "flags": ["cold_blooded"], "desc": "冰原与铁甲之地的人。沉默、耐寒，骨子里埋着北境的雪。"}, "midland": {"cn": "中境人", "race": "human", "attrs": {"INT": 2, "CHA": 1}, "skills": {"lore": 5}, "traits": ["博学"], "desc": "大陆腹地的平原之民。见多识广，学什么都快。"}, "southland": {"cn": "南境人", "race": "human", "attrs": {"CHA": 2, "INT": 1}, "skills": {"bargain": 5}, "traits": ["商才"], "desc": "南方城邦的商人血脉。算盘声比摇篮曲更熟。"}, "eastland": {"cn": "东境人", "race": "human", "attrs": {"INT": 2, "AGI": 1}, "skills": {"craft": 5}, "traits": ["巧手"], "desc": "帝京与工坊之间的人。读书、作画、铸器，样样能上手。"}, "westland": {"cn": "西境人", "race": "human", "attrs": {"CHA": 1, "INT": 1, "AGI": 1}, "skills": {"bargain": 5}, "traits": ["识途"], "desc": "西海岸的航海之民。风浪与远方养大的人。"}, "plateau": {"cn": "高原人", "race": "human", "attrs": {"CON": 2, "STR": 1}, "skills": {"survive": 5}, "traits": ["耐力"], "desc": "高原山地之民。肺活量大，脚步稳，天生能扛。"}, "islander": {"cn": "海岛人", "race": "human", "attrs": {"AGI": 2, "CON": 1}, "skills": {"survive": 5}, "traits": ["水行"], "flags": ["waterborne"], "desc": "群岛之民。船是摇篮，海是庭院。"}, "halfelf": {"cn": "半精灵", "race": "half", "attrs": {"SPR": 2, "CHA": 1}, "skills": {"lore": 5}, "traits": ["夜视", "长寿"], "flags": ["night_vision"], "desc": "人类与精灵的混血。比人长寿，比精灵短命，两边都沾，两边都不全是。"}, "halforc": {"cn": "半兽人", "race": "half", "attrs": {"STR": 2, "CON": 1}, "skills": {"martial": 5}, "traits": ["铁骨"], "desc": "人类与兽人的混血。力量与怒意流淌在血脉里，走到哪里都被人多看一眼。"}, "halfdwarf": {"cn": "半矮人", "race": "half", "attrs": {"CON": 2, "STR": 1}, "skills": {"alchemy": 5}, "traits": ["地脉"], "desc": "人类与矮人的混血。矮小的身板，铁打的胃口，炉火边长大的手艺。"}, "highelf": {"cn": "高等精灵", "race": "elf", "attrs": {"SPR": 2, "INT": 1}, "skills": {"magic": 5}, "traits": ["奥术", "长寿"], "desc": "精灵王庭的高贵血脉。魔法在他们指尖，如同呼吸一般自然。"}, "woodelf": {"cn": "森林精灵", "race": "elf", "attrs": {"AGI": 2, "SPR": 1}, "skills": {"survive": 5}, "traits": ["林语"], "desc": "林间巡猎的精灵。脚步比落叶更轻，箭矢比风更快。"}, "darkelf": {"cn": "黑暗精灵", "race": "elf", "attrs": {"AGI": 2, "SPR": 1}, "skills": {"stealth": 5}, "traits": ["夜视", "影行"], "flags": ["night_vision"], "desc": "地底与阴影中的精灵。银发紫瞳，视线在黑暗里比光更利。"}, "seaelff": {"cn": "海精灵", "race": "elf", "attrs": {"AGI": 1, "CON": 2}, "skills": {"survive": 5}, "traits": ["水行"], "flags": ["waterborne"], "desc": "碧波之下的精灵。鳞光与珊瑚，是他们熟悉的穹顶。"}, "valelf": {"cn": "山谷精灵", "race": "elf", "attrs": {"INT": 1, "CHA": 1, "CON": 1}, "skills": {"craft": 5}, "traits": ["巧手"], "desc": "山谷聚落中的精灵。融手艺、商贾与山地为一体。"}, "hilldwarf": {"cn": "高山矮人", "race": "dwarf", "attrs": {"STR": 1, "CON": 2}, "skills": {"alchemy": 5}, "traits": ["石肤"], "desc": "雄山之中的矮人。打铁、凿石、酿酒，祖传的手艺。"}, "vulcdwarf": {"cn": "火山矮人", "race": "dwarf", "attrs": {"STR": 2, "CON": 1}, "skills": {"craft": 5}, "traits": ["火锻"], "desc": "火山熔炉边的矮人。浑身透着一股硫磺与热铁的味儿。"}, "valdwarf": {"cn": "丘陵矮人", "race": "dwarf", "attrs": {"CHA": 1, "INT": 1, "CON": 1}, "skills": {"bargain": 5}, "traits": ["识途"], "desc": "丘陵农庄间的矮人。酿酒、种麦，也做买卖。"}, "grayelf": {"cn": "灰矮人", "race": "dwarf", "attrs": {"INT": 2, "AGI": 1}, "skills": {"stealth": 5}, "traits": ["夜视", "影行"], "flags": ["night_vision"], "desc": "灰岩地底的矮人。隐于阴影，心思深沉。"}, "seadwarf": {"cn": "海矮人", "race": "dwarf", "attrs": {"CON": 1, "STR": 1, "AGI": 1}, "skills": {"survive": 5}, "traits": ["水行"], "flags": ["waterborne"], "desc": "海岸与船坞的矮人。铁匠兼水手，两样都硬。"}, "plainorc": {"cn": "草原兽人", "race": "orc", "attrs": {"STR": 3}, "skills": {"martial": 5}, "traits": ["战意"], "desc": "草原游牧的兽人。骑术与战歌，是他们与生俱来的语言。"}, "mountorc": {"cn": "山地兽人", "race": "orc", "attrs": {"CON": 2, "STR": 1}, "skills": {"survive": 5}, "traits": ["耐力"], "desc": "山地部族的兽人。攀岩如走平地，耐性惊人。"}, "shadoworc": {"cn": "暗影兽人", "race": "orc", "attrs": {"AGI": 2, "STR": 1}, "skills": {"stealth": 5}, "traits": ["夜视", "影行"], "flags": ["night_vision"], "desc": "暗夜中行动的兽人。潜行如影，一击即走。"}, "swamporc": {"cn": "沼泽兽人", "race": "orc", "attrs": {"CON": 2, "AGI": 1}, "skills": {"survive": 5}, "traits": ["毒抗"], "flags": ["poison_resist"], "desc": "沼泽部族的兽人。泥泞与瘴气，于他们是家常便饭。"}, "hobfarm": {"cn": "田园半身人", "race": "halfling", "attrs": {"AGI": 2, "CHA": 1}, "skills": {"stealth": 5}, "traits": ["幸运"], "flags": ["lucky"], "desc": "田野间的半身人。炊烟、麦田与暖烘烘的炉火。"}, "hobnomad": {"cn": "游牧半身人", "race": "halfling", "attrs": {"AGI": 1, "CHA": 1, "CON": 1}, "skills": {"bargain": 5}, "traits": ["识途"], "desc": "车队里的半身人。跟着商队走四方，好话一箩筐。"}, "hobcity": {"cn": "城市半身人", "race": "halfling", "attrs": {"AGI": 2, "INT": 1}, "skills": {"stealth": 5}, "traits": ["巧手"], "desc": "城巷里的半身人。开锁、探路、讨价还价，样样在行。"}, "reddra": {"cn": "红龙裔", "race": "dragon", "attrs": {"STR": 2, "CON": 1}, "skills": {"martial": 5}, "traits": ["火息"], "desc": "红龙血脉的后裔。吐息灼热，脾气也随血脉一起滚烫。"}, "bluedra": {"cn": "蓝龙裔", "race": "dragon", "attrs": {"INT": 2, "SPR": 1}, "skills": {"magic": 5}, "traits": ["雷语"], "desc": "蓝龙血脉的后裔。电光在血脉里跳跃，天生与魔法亲近。"}, "golddra": {"cn": "金龙裔", "race": "dragon", "attrs": {"SPR": 2, "CHA": 1}, "skills": {"divine": 5}, "traits": ["圣辉"], "desc": "金龙血脉的后裔。鳞甲泛金，天生带着一缕圣洁的气息。"}}; window.SUBRACES = SUBRACES; /* /v60inj:winx2:SUBRACES/ */
const CURRENCY = {"gold": "金龙", "silver": "银月", "copper": "铜星", "rate": "1金龙 = 20银月 = 240铜星", "sub": "1银月 = 12铜星", "note": "艾尔达大陆通用货币（编号18·金融体系）。南方城邦与自由城邦另有本地铸币，一律按此汇率通兑。"}; window.CURRENCY = CURRENCY; /* /v60inj:winx2:CURRENCY/ */
const ENEMIES = {"bandit": {"cn": "山贼", "realm": 0, "power": 6, "hp": 18, "atk": 3, "def": 1, "skills": ["劈砍"], "loot": {"gold": 5, "xp": 8}, "desc": "面黄肌瘦的汉子，手里的刀卷了刃，眼神却狠。"}, "wolf": {"cn": "饿狼", "realm": 0, "power": 5, "hp": 14, "atk": 4, "def": 0, "skills": ["扑咬"], "loot": {"xp": 6, "karma": 1}, "desc": "肋骨根根分明的灰狼，嘴角挂着涎水，蹲在暗处。"}, "thug": {"cn": "地痞", "realm": 0, "power": 7, "hp": 20, "atk": 3, "def": 2, "skills": ["围殴", "叫人"], "loot": {"gold": 8, "xp": 10}, "desc": "街市上的闲汉，胳膊上有刺青，走路横着膀子。"}, "darkcult_acrolyte": {"cn": "暗蚀会爪牙", "realm": 1, "power": 25, "hp": 35, "atk": 6, "def": 3, "skills": ["暗影匕首", "侵蚀触"], "loot": {"gold": 15, "xp": 25, "mat": "暗蚀碎片"}, "desc": "灰袍人，兜帽下的脸半隐在阴影里，指尖泛着不自然的青黑色。"}, "orc_warrior": {"cn": "兽人战士", "realm": 1, "power": 30, "hp": 45, "atk": 8, "def": 4, "skills": ["猛劈", "战吼"], "loot": {"gold": 12, "xp": 30}, "desc": "比常人高出一头的绿皮兽人，战斧比他的腿还粗，鼻环随着呼吸晃动。"}, "mercenary": {"cn": "雇佣兵", "realm": 1, "power": 28, "hp": 40, "atk": 7, "def": 5, "skills": ["剑术", "格挡"], "loot": {"gold": 20, "xp": 28}, "desc": "皮甲上缝着好几块补丁，剑却磨得雪亮。眼神是杀过人的那种平静。"}, "darkcult_enforcer": {"cn": "暗蚀会执行者", "realm": 2, "power": 80, "hp": 70, "atk": 12, "def": 8, "skills": ["暗影链", "侵蚀爆发", "精神低语"], "loot": {"gold": 40, "xp": 60, "mat": "暗蚀核心", "flag": "darkcult_evidence"}, "desc": "黑袍上绣着暗金色的眼形纹章。他走路没有声音，周围的灯火似乎都暗了一度。"}, "elite_guard": {"cn": "精锐卫兵", "realm": 2, "power": 70, "hp": 65, "atk": 10, "def": 12, "skills": ["长枪突刺", "盾阵", "军阵配合"], "loot": {"gold": 30, "xp": 55}, "desc": "全身披甲的卫兵，动作整齐划一，枪尖映着冷光。"}, "beast_alpha": {"cn": "巨兽首领", "realm": 2, "power": 90, "hp": 90, "atk": 15, "def": 6, "skills": ["冲撞", "撕咬", "震地"], "loot": {"gold": 25, "xp": 70, "mat": "兽核"}, "desc": "皮毛如铁的巨兽，每一步都让地面微颤。它的眼睛里，有不寻常的智慧。"}, "darkcult_captain": {"cn": "暗蚀会队长", "realm": 3, "power": 250, "hp": 120, "atk": 20, "def": 15, "skills": ["暗影领域", "侵蚀之刃", "精神压制", "召唤爪牙"], "loot": {"gold": 80, "xp": 120, "mat": "暗蚀徽记", "flag": "darkcult_captain_slain"}, "desc": "兜帽下露出半张脸，另一半覆着黑色的结晶。他抬手时，空气里有细碎的冰晶凝结又碎裂。"}, "veteran_general": {"cn": "沙场老将", "realm": 3, "power": 220, "hp": 110, "atk": 18, "def": 20, "skills": ["军道杀势", "破阵枪", "坚守", "反击"], "loot": {"gold": 100, "xp": 110, "mat": "将令"}, "desc": "须发皆白的老将，铠甲上满是刀痕。他站在那里，像一堵墙。"}, "darkcult_sector_lord": {"cn": "暗蚀会部门主官", "realm": 4, "power": 600, "hp": 200, "atk": 35, "def": 25, "skills": ["领域展开", "侵蚀法则", "精神风暴", "深渊低语"], "loot": {"gold": 200, "xp": 300, "mat": "部门印信", "flag": "sector_lord_encounter"}, "desc": "他没有动手。只是站在那里，你的呼吸就开始困难。灯火朝他的方向倾斜，像在行礼。"}, "legendary_warrior": {"cn": "传奇武者", "realm": 5, "power": 1500, "hp": 350, "atk": 50, "def": 40, "skills": ["意之领域", "一刀", "武道真意"], "loot": {"gold": 500, "xp": 500}, "desc": "你看不清他的动作。你只看见结果——然后才听见刀鸣。"}}; window.ENEMIES = ENEMIES; /* /v60inj:winx2:ENEMIES/ */
const NPC_LIFE = {"aurelian": {"cn": "艾尔达里翁·埃翁", "city": "free", "base": "没落王族后裔，时空系天才。旧怀表、苦茶、独自下棋、写诗然后烧掉。", "events": [{"min": 1, "max": 3, "text": "他常去的那家茶馆换了老板。他坐在老位置上，盯着面前的空茶杯看了很久，然后起身走了。茶钱压在杯底，是一枚旧银币。", "trace": "旧银币"}, {"min": 4, "max": 7, "text": "有人看见他在城墙根下坐了一整夜。面前摆着一盘棋，对面没有坐人。晨光漫上来时，他把棋子一颗颗收进木盒，动作很慢。", "trace": "空棋盘"}, {"min": 8, "max": 14, "text": "他的怀表停了。停在三点十七分——没人知道那是什么时辰。他把表放进抽屉最深处，再没戴出来过。", "trace": "停摆的怀表", "effect": {"karma": 1}}, {"min": 15, "max": 30, "text": "他开始写诗了。写在一种很薄的信纸上，写完就烧掉。灰烬被风卷走，有一片落在邻院的水缸里，漂了三天。", "trace": "诗灰"}, {"min": 31, "max": 999, "text": "他瘦了。颧骨凸出来，眼窝陷下去。但眼神比以前更亮，像在看什么别人看不见的东西。有人说，他偶尔会对着空气说话。", "trace": "消瘦的侧脸"}]}, "roland": {"cn": "罗兰·德·艾恩沃尔", "city": "north", "base": "铁壁公国继承人。打铁、骑马、喝酒、听弟弟弹琴。沉默寡言，一诺千金。", "events": [{"min": 1, "max": 3, "text": "铁匠铺的炉火三天没熄。他在打一把剑，打了又熔，熔了又打。铺子里的伙计说，少爷这几天一句话都没说。", "trace": "未完成的剑"}, {"min": 4, "max": 7, "text": "他弟弟的琴声断了。据说是琴弦崩了一根，崩在一个很高的音上。罗兰站在琴房门口，站了很久，然后转身去了马厩。", "trace": "断弦"}, {"min": 8, "max": 14, "text": "他在演武场练了一整天的枪。最后一枪刺出去时，石制的枪靶裂成了两半。他把枪拄在地上，看着裂缝，看了很久。", "trace": "裂开的枪靶", "effect": {"rep": 2}}, {"min": 15, "max": 30, "text": "北境来了信。他看完信后，把信纸折好放进胸甲内侧。那天晚上，他一个人喝了一坛酒，第二天一早照常去了铁匠铺。", "trace": "胸甲里的信"}, {"min": 31, "max": 999, "text": "他的右手多了一道新疤。从虎口延伸到手腕，很深。他说是打铁时不小心烫的，但铁匠铺的人说，那几天炉子里没烧铁。", "trace": "手上的新疤"}]}, "silvia": {"cn": "西尔维娅·冯·墨丘利", "city": "south", "base": "银月家族商业天才。珠宝、跳舞、品酒、与奥鲁斯关系暧昧。精明而不失温度。", "events": [{"min": 1, "max": 3, "text": "她订的那批珍珠到了。她在灯下一颗颗看，看到最后一颗时，笑了一下——那是这批珍珠里唯一一颗有瑕疵的。她把它单独收了起来。", "trace": "瑕疵珍珠"}, {"min": 4, "max": 7, "text": "舞会上她跳了三支舞。第三支的舞伴不是奥鲁斯。有人注意到，她跳第三支时，视线一直在找什么人。", "trace": "空着的舞伴位"}, {"min": 8, "max": 14, "text": "银月家族的商队在沙漠里遇了沙暴。损失了三成货物。她听到消息时正在品酒，酒杯在指间转了三圈，然后放下，一滴没洒。", "trace": "没洒的酒", "effect": {"gold": -20, "rep": 1}}, {"min": 15, "max": 30, "text": "她开始学一种新的舞步。据说是从东部王国传来的，节奏很怪，忽快忽慢。她练舞时不许人看，仆人们只听见木地板上的脚步声，时急时缓。", "trace": "奇怪的脚步声"}, {"min": 31, "max": 999, "text": "她的珠宝盒里多了一枚戒指。不是银月家族的样式，也不是任何已知商会的款式。她从不戴它，只是偶尔打开盒子看一眼，然后很快合上。", "trace": "无名戒指"}]}, "skadi": {"cn": "斯卡迪·弗罗斯特", "city": "north", "base": "北境冰霜女武神。打猎、木雕、唱民谣。父亲卧床，家族重担在肩。", "events": [{"min": 1, "max": 3, "text": "她猎到了一头白狐。皮毛纯白，没有一根杂色。她把狐皮铺在父亲的床头。父亲摸了摸，说了句什么，她没听清——父亲的声音已经很轻了。", "trace": "白狐皮"}, {"min": 4, "max": 7, "text": "她在木雕一只鸟。雕了三天，鸟的翅膀始终不对称。第四天她把木雕扔进了壁炉。火里飘出松脂的香味，她坐在火边，唱了一首没人听过的歌。", "trace": "烧焦的木屑"}, {"min": 8, "max": 14, "text": "父亲的病加重了。她请了三个医师，第三个走时摇了摇头。她把医师送到门口，回来时脸上没有表情。那天晚上，她的刀磨了一夜。", "trace": "磨了一夜的刀", "effect": {"karma": 1}}, {"min": 15, "max": 30, "text": "她独自去了北境的冰原。七天后回来，带回一块蓝色的冰。冰里封着一朵花，不知道是什么花。她把冰放在父亲的窗台上，至今没化。", "trace": "不化的蓝冰"}, {"min": 31, "max": 999, "text": "她的歌声变了。以前唱的是猎歌和酒歌，现在唱的调子很慢，像在跟什么人告别。北境的老人说，那是挽歌——只有失去至亲的人才唱。", "trace": "挽歌"}]}, "michael": {"cn": "米迦勒·德·本尼迪克特", "city": "church", "base": "圣光骑士。园艺、做饭、孤儿院、对教会腐败感到烦恼。温和但内心挣扎。", "events": [{"min": 1, "max": 3, "text": "孤儿院的菜园丰收了。他给孩子们做了一顿炖菜。有个孩子问他，神父说的天堂是不是真的。他愣了一下，然后摸了摸孩子的头，说：先把菜吃完。", "trace": "空了的菜盆"}, {"min": 4, "max": 7, "text": "他在教堂的忏悔室里坐了一整夜。第二天出来时，眼睛是红的。他没说听到了什么，只是把一把钥匙交给了院长——那是教堂地下室的钥匙。", "trace": "地下室钥匙"}, {"min": 8, "max": 14, "text": "教会的税收又涨了。他去议事厅争辩，争到最后，主教拍了桌子。他从议事厅出来时，阳光正好照在他的铠甲上，但他觉得冷。", "trace": "冰冷的铠甲", "effect": {"rep": 1, "karma": 1}}, {"min": 15, "max": 30, "text": "他开始教孤儿院的孩子们认字。用的课本不是教会发的，是他自己抄的。抄到第三本时，手指磨出了茧。他把茧给孩子们看，说：这是写字写出来的，不是打仗打的。", "trace": "抄书的茧"}, {"min": 31, "max": 999, "text": "他的剑很久没拔出来过了。剑鞘上落了一层灰。但他的锄头磨得很亮。有人问他，骑士不练剑了吗？他说：剑是保护人的，锄头也是。", "trace": "蒙尘的剑"}]}, "innkeeper_free": {"cn": "灰港酒馆老板娘", "city": "free", "base": "泼辣精明，消息灵通。", "events": [{"min": 1, "max": 5, "text": "酒馆里来了个生人，包了楼上的房间，三天没出门。老板娘给他送饭时，看见桌上摊着一张地图，地图上画了好几个红圈。", "trace": "地图上的红圈"}, {"min": 6, "max": 15, "text": "酒馆的招牌换了。新招牌上画着一只金色的麦穗——那是银穗商路的标记。老板娘说，换个招牌，图个吉利。", "trace": "金麦穗招牌"}, {"min": 16, "max": 999, "text": "老板娘的手腕上多了一道淤青。她说是搬酒桶时撞的，但酒桶在地下室，她最近根本没下去过。", "trace": "手腕的淤青"}]}, "blacksmith_north": {"cn": "北境铁匠", "city": "north", "base": "沉默寡言，打铁三十年。", "events": [{"min": 1, "max": 5, "text": "铁匠铺接了一笔大订单——一百把长枪。铁匠没问是谁要的，只是日夜赶工。炉火映着他的脸，他的表情比铁还硬。", "trace": "一百把长枪的订单"}, {"min": 6, "max": 999, "text": "铁匠的左手少了一根小指。他说是打铁时被铁料砸的。但铺子里的学徒说，那天晚上有个穿黑袍的人来过，走后铁匠就少了一根手指。", "trace": "少了的小指"}]}, "merchant_south": {"cn": "南方商会管事", "city": "south", "base": "八面玲珑，算盘比脑子快。", "events": [{"min": 1, "max": 5, "text": "商会的账房烧了一本账。管事说，是陈年旧账，留着没用。但烧账那天，他在密室里待到后半夜，出来时脸色发白。", "trace": "烧账的灰"}, {"min": 6, "max": 999, "text": "管事新买了一处宅子。在城南，很偏僻。他从不在那里过夜，只是每隔几天去一趟，每次都带着一个布包，出来时布包是空的。", "trace": "城南的空宅"}]}}; window.NPC_LIFE = NPC_LIFE; /* /v60inj:winx2:NPC_LIFE/ */

